import heapq
from collections import defaultdict


def build_order(tables: list[str], deps: list[tuple[str, str]]) -> list[str]:
    downstream: dict[str, set[str]] = defaultdict(set)
    indegree = {t: 0 for t in tables}
    for up, down in set(deps):
        downstream[up].add(down)
        indegree[down] += 1
    ready = [t for t, d in indegree.items() if d == 0]
    heapq.heapify(ready)
    order: list[str] = []
    while ready:
        table = heapq.heappop(ready)
        order.append(table)
        for nxt in downstream[table]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(ready, nxt)
    if len(order) != len(tables):
        raise ValueError("dependency cycle detected")
    return order
